export function BulkOperations({
  actionLabel = "{{actionLabel}}",
  selectedCount = "{{selectedCount}}",
  accent = "{{accent}}",
  showBar = {{showBar}},
}) {
  const n = Number(selectedCount);
  const rows = ["Invoice 001", "Invoice 002", "Invoice 003", "Invoice 004"];
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 14, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      {rows.map((label, i) => (
        <div key={label} style={{ display: "flex", alignItems: "center", gap: 10, padding: "8px 6px", borderBottom: "1px solid #24143014" }}>
          <span style={{ width: 16, height: 16, borderRadius: 4, boxSizing: "border-box", flexShrink: 0, border: i < n ? "2px solid #241430" : "2px solid #24143040", background: i < n ? "#241430" : "transparent" }} />
          {label}
        </div>
      ))}
      {showBar && n > 0 && (
        <div role="status" style={{ marginTop: 10, padding: "10px 12px", borderRadius: 8, fontSize: 12, textAlign: "center", color: "#241430", background: accent }}>
          {selectedCount} selected &mdash; <strong>{actionLabel}</strong>
        </div>
      )}
    </div>
  );
}
